insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-subjects-card-design-to-every-card-sam-2026-11-24','decision','Finish the Subjects work and carry the Subjects card''s design to the other Commons cards','Sam, 2026-11-24 ~01:20Z, opening S719: "In this session, let''s finish the subjects work and apply the design from the subject card to the other commons cards." Done: #3740 and #3741 (Subjects), #3743 (every card but Plan in the checks design), #3745 (the MQ view), #3748 (the cards answer their own edits; his S715 ask 3).',array['commons','subjects','cards','design'],'verified','Sam in session S719; PRs #3740, #3741, #3743, #3745, #3748','Sam',now(),'SkyShearwater (S719)','2026-11-24'),
('d-program-label-lists-the-codes-courses-s719','decision','A program label is filed for a code only when the program''s page lists the code''s courses as its own','S719, Sky''s call, Sam''s to revise (#3741): a program label is filed for a local subject code only when the program''s page lists the code''s courses as its own, never when a program requires one or two of them. Two labels were dropped on it: Southwest FAM & CS and West Los Angeles ALD HTH.',array['commons','subjects','web-search','collection'],'proposed','PR #3741',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-search-row-records-its-own-query-s719','decision','A web-search row records only a query run for that code','S719, Sky''s call, Sam''s to revise (#3741): a row in kb/reference/subject_web_searches.json records only a query run for that code. A grouped search across several codes does not stand for a row; one helper had recorded per-row queries that were never run for those codes.',array['commons','subjects','web-search','provenance'],'proposed','PR #3741',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-cards-checks-design-s719','decision','Every Commons card but Plan takes the checks design; a Confident line only where a score is measured','S719, Sky''s call, Sam''s to revise (#3743): every Commons card but Plan takes the Subjects card''s design (checksCard in commons_front.js: quick links, Why, Finished when, Confident, Scale, folded Collect/Curate/Connect checks with Where to act). A Confident line appears only where a card reads a measured score: Courses and M-IDs alone, its count at 0.9 TBA.',array['commons','cards','design'],'proposed','PR #3743',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-cards-live-figures-s719','decision','Which Commons card figures recount from the live saves and which stay committed-only','S719, Sky''s call, Sam''s to revise (#3748): live are Exhibit titles (held, stamped), Courses data (outlines to find drop with each hand-over) and Credit Recommendations (settled, from cr_reference_decisions; the carry stamp is the last receipt''s day). Committed-only, each with its reason in the method text: Courses and M-IDs, College Data Collection''s stuck colleges, Programs.',array['commons','cards','live-figures'],'proposed','PR #3748',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-mq-view-addresses-s719','decision','The MQ view''s address shapes and its seven columns','S719, Sky''s call, Sam''s to revise (#3745): the MQ view opens at #commons/subjects/mq and /mq/code/<CODE>; the statewide list''s code filter at #commons/subjects/statewide/code/<CODE>; a second sidebar at .../courses/<LOCAL> and .../colleges/<LOCAL>. Seven columns: COCI noncredit categories under MQ type, the vocational TOP share under M-IDs.',array['commons','subjects','mq-view','csr'],'proposed','PR #3745',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-second-sidebar-beside-first-s719','decision','A second sidebar opens beside the first, which narrows to about 320px','S719, Sky''s call, Sam''s to revise (#3745): a count in a sidebar opens a second sidebar beside the first, which narrows to about 320px; the view gives up their width, and the pair covers it only when no room is left. Next: with both open, the view''s last ~124px strip should give way to the pair.',array['commons','subjects','sidebar','ui'],'proposed','PR #3745',null,null,'SkyShearwater (S719)','2026-11-24'),
('d-csr-baseline-20th-s719','decision','The quarterly MQ baseline is the 20th edition, tied to the committed handbook file','S719, Sky''s call, Sam''s to revise (#3744): csr-quarterly.yml''s baseline is the 20th edition, the address and sha256 kb/reference/mq_handbook_20th.json was read from; dispatch run 45311236371 printed COMPARE same, 2,983,718 bytes. tests/csr_quarterly_probe_test.py ties the baseline to that file, not to an edition number.',array['csr','mq-disciplines','quarterly','baseline'],'proposed','PR #3744; run 45311236371',null,null,'SkyShearwater (S719)','2026-11-24'),
('f-southwestern-pe-es-behind-robots-s719','fact','Southwestern''s PE to ES renames are printed in an archive robots.txt closes; nothing filed','S719: Southwestern''s 2017-2018 catalog archive prints "Formerly PE/..." beside its ES courses and answers robots_disallow (run 45304973641); the current catalog prints only "Formerly: ES/L ..." on ES/S courses (run 45305645978). COCI''s PE/D matches DANC 3 of 3; 19 of PE/A''s 22 numbers sit under ES/A. Nothing filed; waits on Sam''s word or a printed source.',array['commons','subjects','subject-code-history','southwestern'],'proposed','PR #3741; runs 45304973641, 45305645978',null,null,'SkyShearwater (S719)','2026-11-24'),
('f-renames-microtk-it-dsps-accs-s719','fact','LATTC MICROTK to IT and Mt. San Antonio DSPS to ACCS: likely renames, not read in print','S719 (#3741): a search summary says LATTC''s 2026-2027 catalog prints IT 077-079 as formerly MICROTK, and Mt. San Antonio''s DSPS page reads "Access (ACCS)". Both are likely renames for kb/reference/subject_code_history/ and wait for a read of the printed line; a search summary is not the page.',array['commons','subjects','subject-code-history','web-search'],'proposed','PR #3741',null,null,'SkyShearwater (S719)','2026-11-24'),
('f-mq-sections-still-19th-s719','fact','The quarterly probe''s committed edition still reads 19 because mq_sections.json is a 19th-edition read','S719 (#3744): after the re-baseline, kb/_csr_quarterly_probe.py''s committed_edition still reads 19, because kb/reference/mq_sections.json was read from the 19th edition. Informational; the next step is to re-read mq_sections.json from the 20th edition.',array['csr','mq-disciplines','quarterly'],'proposed','PR #3744',null,null,'SkyShearwater (S719)','2026-11-24'),
('m-s719-subjects-and-commons-cards','milestone','S719: the Subjects web-search pass, the MQ view, every Commons card in the Subjects design','S719 SkyShearwater, 2026-11-24: merged #3740 (levels() matches names as the table does), #3741 (the web-search pass for all 205 untitled codes; 313 searches on file), #3743 (the cards'' checks design), #3744 (the 20th-edition baseline), #3745 (the MQ view, the second sidebar); open at the checkpoint #3748 (the cards answer their own edits). Handoff 720.',array['commons','subjects','csr','milestone'],'proposed','PRs #3740, #3741, #3743, #3744, #3745, #3748; docs/session_720_handoff.md',null,null,'SkyShearwater (S719)','2026-11-24')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
